  117	            } while (anonymity !== this.anonymity);
  118	
  119	            const initResult = this.posthog.init(posthogConfig.projectApiKey, {
  120	                api_host: posthogConfig.apiHost,
  121	                autocapture: false,
  122	                mask_all_text: true,
  123	                mask_all_element_attributes: true,
  124	                sanitize_properties: this.sanitizeProperties.bind(this),
  125	            });
  126	            if (initResult && typeof (initResult as any).then === "function") {
  127	                await initResult;
  128	            }
  129	            this.initialised = true;
  130	        } catch (error) {
  131	            this.enabled = false;
  132	            this.initialised = false;
  133	            throw error;
  134	        }
  135	    }
