  137	    private toAnonymity(anonymity: Anonymity | boolean): Anonymity {
  138	        // Keep supporting the previous boolean init argument: true meant anonymous, false
  139	        // meant pseudonymous.
  140	        if (typeof anonymity === "boolean") {
  141	            return anonymity ? Anonymity.Anonymous : Anonymity.Pseudonymous;
  142	        }
  143	        return anonymity === Anonymity.Pseudonymous ? Anonymity.Pseudonymous : Anonymity.Anonymous;
  144	    }
