  162	    private updateRedactedCurrentLocation(): Promise<void> | void {
  163	        // TODO only calculate this when the location changes as its expensive
  164	        const { origin, hash, pathname } = window.location;
  165	        const [marker, originalScreen, ...pathSegments] = hash.split("/");
  166	
  167	        // Anonymous locations and routes without private path segments can be prepared
  168	        // synchronously. Pseudonymous routes with private segments need Web Crypto.
  169	        if (this.anonymity === Anonymity.Anonymous || pathSegments.length === 0) {
  170	            const screen = knownScreens.has(originalScreen) ? originalScreen : "<redacted_screen_name>";
  171	            const safePath = this.anonymity === Anonymity.Anonymous ?
  172	                pathSegments.map(() => "<redacted>") : pathSegments;
  173	            const safePathname = origin.startsWith("file://") ? "/<redacted_file_scheme_url>/" : pathname;
  174	            this.redactedCurrentLocation = `${origin}${safePathname}${marker}/${screen}/${safePath.join("/")}`;
  175	            return;
  176	        }
  177	
  178	        return getRedactedCurrentLocation(origin, hash, pathname, this.anonymity).then((location) => {
  179	            this.redactedCurrentLocation = location;
  180	        });
  181	    }
