  183	    private sanitizeProperties(properties: posthog.Properties, _: string): posthog.Properties {
  184	        // Sanitize posthog's built in properties which leak PII e.g. url reporting
  185	        // see utils.js _.info.properties in posthog-js
  186	
  187	        // this.redactedCurrentLocation needs to have been updated prior to reaching this point as
  188	        // updating it involves async, which this callback is not
  189	        properties['$current_url'] = this.redactedCurrentLocation;
  190	
  191	        if (this.anonymity === Anonymity.Anonymous) {
  192	            // drop referrer information for anonymous users
  193	            properties['$referrer'] = null;
  194	            properties['$referring_domain'] = null;
  195	            properties['$initial_referrer'] = null;
  196	            properties['$initial_referring_domain'] = null;
  197	
  198	            // drop device ID, which is a UUID persisted in local storage
  199	            properties['$device_id'] = null;
  200	        }
  201	
  202	        return properties;
  203	    }
