  228	    private canCapture(eventAnonymity: Anonymity): boolean {
  229	        if (!this.enabled) return false;
  230	        if (eventAnonymity === Anonymity.Pseudonymous && this.anonymity === Anonymity.Anonymous) return false;
  231	        if (!this.initialised) {
  232	            throw new Error("PostHog analytics is enabled but has not finished initializing");
  233	        }
  234	        return true;
  235	    }
