  237	    private async capture(eventName: string, properties: posthog.Properties, eventAnonymity: Anonymity): Promise<void> {
  238	        if (!this.canCapture(eventAnonymity)) return;
  239	
  240	        let anonymity: Anonymity;
  241	        do {
  242	            anonymity = this.anonymity;
  243	            const locationUpdate = this.updateRedactedCurrentLocation();
  244	            if (locationUpdate) await locationUpdate;
  245	            if (!this.canCapture(eventAnonymity)) return;
  246	        } while (anonymity !== this.anonymity);
  247	
  248	        await this.posthog.capture(eventName, properties);
  249	    }
